#!/bin/bash
# The planner items that the first full pass did not cover (planner 5.3, 7.2).
#   bash run_gap.sh [workers]
# hard : adds DeepSynergy to leave_drug / leave_cell / leave_tumor (34 new runs) - it is the
#        strongest model in the main table, so the hard-split table was missing its key column
# xgb  : the Morgan-fingerprint + expression gradient-boosting baseline (89 runs)
# Do not edit this file while it runs.
set -u
cd "$(dirname "$0")"
export PYTHONPATH=.
W=${1:-4}
LOG=runs/pipeline.log
say() { echo "[$(date +%H:%M:%S)] $*" | tee -a $LOG; }
say "stage hard (+deepsynergy)"; python -m src.sweep --stage hard --workers "$W" >> $LOG 2>&1
say "stage xgb";                 python -m src.sweep --stage xgb  --workers "$W" >> $LOG 2>&1
say "report";                    python -m src.eval.report >> $LOG 2>&1
say "gap done"
